    /**
     * Method to retrieve the Dashboard via DashboardFetchOneSummary
     * @param 	summary DashboardFetchOneSummary 
     * @return 	DashboardFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Dashboard getDashboard( DashboardFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DashboardFetchOneSummary arg cannot be null" );
    	
    	Dashboard entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Dashboard
        	// --------------------------------------
        	CompletableFuture<Dashboard> futureEntity = queryGateway.query(new FindDashboardQuery( new LoadDashboardFilter( summary.getDashboardId() ) ), ResponseTypes.instanceOf(Dashboard.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Dashboard with id " + summary.getDashboardId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


